struct TmpVault {
    p: PathBuf,
}

impl Drop for TmpVault {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.p);
    }
}

fn vault(name: &str) -> TmpVault {
    let p = std::env::temp_dir().join(format!("koios-synth-{name}-{}", std::process::id()));
    let _ = fs::remove_dir_all(&p);
    koios::init_vault(&p).unwrap();
    TmpVault { p }
}

/// The fixture PY_TYPICAL was generated from — one source of truth so the render
/// test can never drift from the strings actually compared against Python.
fn typical_facts() -> Vec<(String, String)> {
    [
        ("营收 32 亿", "r.md#财务分析/1"),
        ("负债 18 亿", "r.md#负债分析/2"),
        ("现金流为正", "r.md#现金流/3"),
        ("毛利率 41%", "r.md#财务分析/4"),
        ("研发投入 3 亿", "r.md#研发/5"),
        ("海外收入占比 22%", "r.md#营收结构/6"),
        ("存货周转 5.2 次", "r.md#营运/7"),
        ("应收账款 9 亿", "r.md#营运/8"),
        ("资本开支 4 亿", "r.md#现金流/9"),
        ("员工 1200 人", "r.md#人力/10"),
    ]
    .iter()
    .map(|(t, b)| (t.to_string(), b.to_string()))
    .collect()
}

fn s(v: &[&str]) -> Vec<String> {
    v.iter().map(|x| x.to_string()).collect()
}

fn touch(v: &std::path::Path, name: &str) {
    let d = v.join("wiki").join("synthesis");
    fs::create_dir_all(&d).unwrap();
    fs::write(d.join(name), "# outdated\n").unwrap();
}

// ------------------------------------------------------------- render parity --

/// render_synthesis must be byte-identical to Python, caps included: facts are
/// sliced to 8 for the body, 3 for `sources`, entities to 10.
#[test]
fn render_matches_python_typical() {
    let got = render_synthesis(
        "finance",
        &s(&["acme", "beta", "gamma"]),
        &typical_facts(),
        "2026-10-08",
        false,
    );
    assert_eq!(got, PY_TYPICAL, "full page must match Python byte for byte");
}

