/// The caps only bite above the threshold — verify the 9th fact and 11th entity
/// are dropped while exactly 8/10 survive. An off-by-one here is invisible to
/// eyeballing a rendered page.
#[test]
fn render_caps_facts_at_eight_and_entities_at_ten() {
    let page = render_synthesis(
        "caps",
        &(1..=12).map(|i| format!("e{i}")).collect::<Vec<_>>(),
        &typical_facts(),
        "2026-10-08",
        false,
    );
    assert!(page.contains("- 应收账款 9 亿"), "8th fact must be present");
    assert!(!page.contains("资本开支 4 亿"), "9th fact must be dropped");
    assert!(page.contains("- [[entities/e10]]"), "10th entity kept");
    assert!(!page.contains("[[entities/e11]]"), "11th entity dropped");
    // `sources` caps at 3 ids even though the body lists 8 — check the LINE,
    // not the whole page: `r.md#财务分析/4` legitimately appears further down.
    let src = page
        .lines()
        .find(|l| l.starts_with("sources:"))
        .expect("sources line");
    assert_eq!(
        src,
        "sources: [raw/r.md#财务分析/1, raw/r.md#负债分析/2, raw/r.md#现金流/3]"
    );
}

#[test]
fn stamp_now_is_utc_iso_date() {
    let d = stamp_now();
    assert_eq!(d.len(), 10, "date stamp must be YYYY-MM-DD; got {d}");
    assert_eq!(&d[4..5], "-");
    assert_eq!(&d[7..8], "-");
    assert!(d.chars().all(|c| c.is_ascii_digit() || c == '-'));
}

