// ------------------------------------------------------- mark_syntheses_stale --

#[test]
fn mark_all_when_topics_is_none() {
    let v = vault("all");
    touch(&v.p, "a.md");
    touch(&v.p, "b.md");
    let conn = connect(&v.p).unwrap();
    let touched = mark_syntheses_stale(&conn, &v.p, None).unwrap();
    // sorted by filename, same as Python's sorted(glob(...))
    assert_eq!(touched, vec!["wiki/synthesis/a.md", "wiki/synthesis/b.md"]);
    assert!(koios::state::is_stale(&conn, "wiki/synthesis/a.md"));
    assert!(koios::state::is_stale(&conn, "wiki/synthesis/b.md"));
}

#[test]
fn mark_only_named_topics() {
    let v = vault("filtered");
    touch(&v.p, "finance.md");
    touch(&v.p, "risk.md");
    touch(&v.p, "ops.md");
    let conn = connect(&v.p).unwrap();
    let touched = mark_syntheses_stale(&conn, &v.p, Some(&["finance".to_string()])).unwrap();
    assert_eq!(touched, vec!["wiki/synthesis/finance.md"]);
    assert!(koios::state::is_stale(&conn, "wiki/synthesis/finance.md"));
    // the whole point of `topics`: these must NOT have been flagged
    assert!(
        !koios::state::is_stale(&conn, "wiki/synthesis/risk.md"),
        "topics must narrow the blast radius"
    );
    assert!(!koios::state::is_stale(&conn, "wiki/synthesis/ops.md"));
}

#[test]
fn mark_syntheses_stale_no_dir_is_empty() {
    let v = vault("nodir");
    let conn = connect(&v.p).unwrap();
    let touched = mark_syntheses_stale(&conn, &v.p, None).unwrap();
    assert!(
        touched.is_empty(),
        "missing synthesis dir -> nothing touched"
    );
}

#[test]
fn topics_are_trimmed_and_empty_entries_dropped() {
    let v = vault("trim");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();
    let touched = mark_syntheses_stale(
        &conn,
        &v.p,
        Some(&["  finance  ".to_string(), "  ".to_string()]),
    )
    .unwrap();
    assert_eq!(touched, vec!["wiki/synthesis/finance.md"]);
}

#[test]
fn empty_topics_list_marks_nothing() {
    // Python: `wanted = {t.strip() for t in topics if t and t.strip()}` -> {} —
    // an empty SET, not None, so `p.stem not in wanted` filters everything out.
    let v = vault("emptytopics");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();
    let touched = mark_syntheses_stale(&conn, &v.p, Some(&[])).unwrap();
    assert!(
        touched.is_empty(),
        "Some([]) matches nothing, unlike None which matches all"
    );
    assert!(!koios::state::is_stale(&conn, "wiki/synthesis/finance.md"));
}

// --------------------------------------------------------- recompile clears --

#[test]
fn recompile_writes_page_and_clears_stale() {
    let v = vault("recompile");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();
    mark_syntheses_stale(&conn, &v.p, None).unwrap();
    assert!(needs_recompile(&conn, &v.p, "finance"));

    let facts = [("营收 32 亿".to_string(), "r.md#财务分析/1".to_string())];
    let target = recompile_synthesis(&conn, &v.p, "finance", &s(&["acme"]), &facts).unwrap();
    assert_eq!(
        target,
        v.p.join("wiki").join("synthesis").join("finance.md")
    );
    assert!(
        !needs_recompile(&conn, &v.p, "finance"),
        "recompile must clear the stale flag or lazy update never terminates"
    );

    let text = fs::read_to_string(&target).unwrap();
    assert!(
        text.contains("[[raw/r.md#财务分析/1]]"),
        "must cite raw (P6)"
    );
    assert!(text.contains("[[entities/acme]]"));
    assert!(text.contains("stale: false"));
    // identical to what Python's recompile writes for the same inputs
    assert_eq!(
        text,
        render_synthesis("finance", &s(&["acme"]), &facts, &stamp_now(), false)
    );
}

#[test]
fn recompile_records_recompiled_reason_and_active_state() {
    let v = vault("rowstate");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();
    mark_syntheses_stale(&conn, &v.p, None).unwrap();
    recompile_synthesis(&conn, &v.p, "finance", &[], &[]).unwrap();
    // Normalised key (see `state::normalize_page_key`): the cascade and the
    // reader must agree on what a page is called, or §8.3 resolves nothing.
    let (stale, state, reason): (i64, String, String) = conn
        .query_row(
            "SELECT stale,state,reason FROM page_state WHERE page_path=?",
            rusqlite::params![koios::state::normalize_page_key(
                "wiki/synthesis/finance.md"
            )],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
        )
        .unwrap();
    assert_eq!(stale, 0);
    // Recompiling clears staleness; it does not overwrite a human's lifecycle
    // state. This page was never disputed, so it reads active.
    assert_eq!(state, "active");
    assert_eq!(reason, "recompiled");
}

#[test]
fn recompile_preserves_a_disputed_state() {
    let v = vault("disputed");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();
    koios::state::set_page_state(
        &conn,
        "wiki/synthesis/finance.md",
        0,
        "disputed",
        "human flagged",
    )
    .unwrap();
    mark_syntheses_stale(&conn, &v.p, None).unwrap();
    recompile_synthesis(&conn, &v.p, "finance", &[], &[]).unwrap();
    let all: Vec<(String, i64, String)> = conn
        .prepare("select page_path,stale,state from page_state")
        .unwrap()
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
        .unwrap()
        .filter_map(Result::ok)
        .collect();
    let (stale, state): (i64, String) = conn
        .query_row(
            "SELECT stale,state FROM page_state WHERE page_path=?",
            rusqlite::params![koios::state::normalize_page_key(
                "wiki/synthesis/finance.md"
            )],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .unwrap();
    assert_eq!(stale, 0, "recompile clears the staleness flag; rows={all:?}");
    assert_eq!(
        state, "disputed",
        "recompile must not silently clear a human's lifecycle state; rows={all:?}"
    );
}

#[test]
fn recompile_creates_page_when_absent() {
    let v = vault("create");
    let conn = connect(&v.p).unwrap();
    let target = recompile_synthesis(&conn, &v.p, "newtopic", &[], &[]).unwrap();
    assert!(target.exists(), "recompile must create page and dir");
    assert!(!needs_recompile(&conn, &v.p, "newtopic"));
    assert!(fs::read_to_string(&target).unwrap().contains("- (暂无)"));
}

/// Port of tests/test_state_cascade.py::test_lazy_synthesis, end to end.
#[test]
fn lazy_synthesis_lifecycle() {
    let v = vault("lifecycle");
    touch(&v.p, "finance.md");
    let conn = connect(&v.p).unwrap();

    assert!(!needs_recompile(&conn, &v.p, "finance"));
    mark_syntheses_stale(&conn, &v.p, None).unwrap();
    assert!(
        needs_recompile(&conn, &v.p, "finance"),
        "lazy update not flagged"
    );

    recompile_synthesis(
        &conn,
        &v.p,
        "finance",
        &s(&["acme"]),
        &[("营收 32 亿".to_string(), "r.md#财务分析/1".to_string())],
    )
    .unwrap();
    assert!(
        !needs_recompile(&conn, &v.p, "finance"),
        "stale flag not cleared"
    );
    let text = fs::read_to_string(v.p.join("wiki").join("synthesis").join("finance.md")).unwrap();
    assert!(text.contains("[[raw/"));
}
